        Pos(r - 1, c), Pos(r, c + 1), Pos(r, c - 1), Pos(r + 1, c),
        Pos(r + 1, c + 1), Pos(r + 1, c - 1), Pos(r - 1, c + 1), Pos(r - 1, c - 1),
